"use strict";

const PRODUCTS = [
  {
    id: "1-key",
    name: "1-Key Clicker",
    price: 2.49,
    image: "data:image/webp;base64,",
    badge: "Pocket pick",
    description: "One compact mechanical key for quick, satisfying clicks anywhere."
  },
  {
    id: "2-key",
    name: "2-Key Clicker",
    price: 3.99,
    image: "data:image/webp;base64,",
    badge: "Easy rhythm",
    description: "A two-key pair that stays portable while giving your fingers more variety."
  },
  {
    id: "3-key",
    name: "3-Key Clicker",
    price: 4.99,
    image: "data:image/webp;base64,",
    badge: "Fan favorite",
    description: "Three mechanical keys in a balanced row for a fuller fidget pattern."
  },
  {
    id: "4-key",
    name: "4-Key Clicker",
    price: 7.49,
    image: "data:image/webp;base64,",
    badge: "Maximum clicks",
    description: "Four keys for the biggest tactile setup in the standard clicker lineup."
  }
];

const KEYCAPS = [
  { id: 1, name: "Keycap 1", image: "data:image/webp;base64," },
  { id: 2, name: "Keycap 2", image: "data:image/webp;base64," },
  { id: 3, name: "Keycap 3", image: "data:image/webp;base64," },
  { id: 4, name: "Keycap 4", image: "data:image/webp;base64," },
  { id: 5, name: "Keycap 5", image: "data:image/webp;base64," },
  { id: 6, name: "Keycap 6", image: "data:image/webp;base64," },
  { id: 7, name: "Keycap 7", image: "data:image/webp;base64," },
  { id: 8, name: "Keycap 8", image: "data:image/webp;base64," },
  { id: 9, name: "Keycap 9", image: "data:image/webp;base64," },
  { id: 10, name: "Keycap 10", image: "data:image/webp;base64," },
  { id: 11, name: "Keycap 11", image: "data:image/webp;base64," }
];

const STORAGE_KEY = "fidgetClickerCartV1";
const CHECKOUT_URL = ""; // Paste a hosted Stripe/PayPal/Square checkout URL here when ready.

let cart = loadCart();
let toastTimer;

const productGrid = document.getElementById("productGrid");
const cartDrawer = document.getElementById("cartDrawer");
const cartOverlay = document.getElementById("cartOverlay");
const cartItems = document.getElementById("cartItems");
const cartCount = document.getElementById("cartCount");
const cartSubtotal = document.getElementById("cartSubtotal");
const openCartButton = document.getElementById("openCartButton");
const shopCartButton = document.getElementById("shopCartButton");
const closeCartButton = document.getElementById("closeCartButton");
const clearCartButton = document.getElementById("clearCartButton");
const checkoutButton = document.getElementById("checkoutButton");
const checkoutModal = document.getElementById("checkoutModal");
const checkoutSummary = document.getElementById("checkoutSummary");
const checkoutMessage = document.getElementById("checkoutMessage");
const copyOrderButton = document.getElementById("copyOrderButton");
const closeCheckoutButton = document.getElementById("closeCheckoutButton");
const toast = document.getElementById("toast");
const builderKeyCountOptions = document.getElementById("builderKeyCountOptions");
const builderSwitchOptions = document.getElementById("builderSwitchOptions");
const builderPositions = document.getElementById("builderPositions");
const builderKeycapGrid = document.getElementById("builderKeycapGrid");
const builderSummary = document.getElementById("builderSummary");
const builderAddButton = document.getElementById("builderAddButton");
const builderPrice = document.getElementById("builderPrice");

const builderState = {
  keyCount: 1,
  switchType: "clicky",
  keycaps: [null],
  activePosition: 0
};

function loadCart() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved || typeof saved !== "object") return {};

    return Object.fromEntries(
      Object.entries(saved)
        .filter(([id, quantity]) => getProduct(id) && Number.isInteger(quantity) && quantity > 0)
    );
  } catch {
    return {};
  }
}

function saveCart() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(cart));
}

function formatMoney(amount) {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD"
  }).format(amount);
}

function capitalize(value) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function getCustomProduct(productId) {
  const match = /^custom-(\d)-(clicky|creamy)-([0-9.]+)$/.exec(productId);
  if (!match) return null;

  const keyCount = Number(match[1]);
  const switchType = match[2];
  const keycaps = match[3].split(".").map(Number);

  if (keyCount < 1 || keyCount > 4 || keycaps.length !== keyCount) return null;
  if (keycaps.some((id) => !KEYCAPS.some((keycap) => keycap.id === id))) return null;

  const baseProduct = PRODUCTS.find((product) => product.id === `${keyCount}-key`);
  if (!baseProduct) return null;

  const configurationText = [
    capitalize(switchType),
    ...keycaps.map((keycapId, index) => `Key ${index + 1}: #${keycapId}`)
  ].join(" • ");

  return {
    id: productId,
    name: `Custom ${keyCount}-Key Clicker`,
    price: baseProduct.price,
    image: baseProduct.image,
    badge: "Custom",
    description: configurationText,
    configurationText,
    custom: true
  };
}

function getProduct(productId) {
  return PRODUCTS.find((product) => product.id === productId) || getCustomProduct(productId);
}

function cartEntries() {
  return Object.entries(cart)
    .map(([id, quantity]) => ({ product: getProduct(id), quantity }))
    .filter((entry) => entry.product && entry.quantity > 0);
}

function cartItemCount() {
  return cartEntries().reduce((sum, entry) => sum + entry.quantity, 0);
}

function cartTotal() {
  return cartEntries().reduce((sum, entry) => sum + (entry.product.price * entry.quantity), 0);
}

function renderProducts() {
  productGrid.innerHTML = PRODUCTS.map((product) => `
    <article class="product-card">
      <div class="product-image">
        <img src="${product.image}" alt="${product.name}">
        <span class="product-badge">${product.badge}</span>
      </div>
      <div class="product-info">
        <h3>${product.name}</h3>
        <p>${product.description}</p>
        <div class="product-row">
          <span class="price">${formatMoney(product.price)}</span>
          <button class="button primary add-button" type="button" data-add-product="${product.id}">Add to cart</button>
        </div>
      </div>
    </article>
  `).join("");

  const byId = Object.fromEntries(PRODUCTS.map((product) => [product.id, product]));
  const miniMix = byId["1-key"].price + byId["2-key"].price;
  const clickCrew = PRODUCTS.reduce((sum, product) => sum + product.price, 0);
  document.getElementById("miniMixPrice").textContent = formatMoney(miniMix);
  document.getElementById("clickCrewPrice").textContent = formatMoney(clickCrew);
}

function renderCart() {
  const entries = cartEntries();
  cartCount.textContent = String(cartItemCount());
  cartSubtotal.textContent = formatMoney(cartTotal());
  checkoutButton.disabled = entries.length === 0;
  checkoutButton.style.opacity = entries.length === 0 ? ".5" : "1";
  checkoutButton.style.cursor = entries.length === 0 ? "not-allowed" : "pointer";

  if (entries.length === 0) {
    cartItems.innerHTML = `
      <div class="empty-cart">
        <div>
          <div style="font-size:2.4rem; margin-bottom:8px;" aria-hidden="true">🛒</div>
          <strong>Your cart is ready for clicks.</strong>
          <span>Add a fidget from the shop and it will appear here.</span>
        </div>
      </div>
    `;
    return;
  }

  cartItems.innerHTML = entries.map(({ product, quantity }) => `
    <article class="cart-item">
      <img class="cart-thumb" src="${product.image}" alt="">
      <div>
        <h3>${product.name}</h3>
        <div class="cart-item-price">${formatMoney(product.price)} each</div>
        ${product.configurationText ? `<div class="cart-config">${product.configurationText}</div>` : ""}
        <div class="quantity" aria-label="Quantity for ${product.name}">
          <button type="button" data-qty-product="${product.id}" data-qty-delta="-1" aria-label="Decrease ${product.name} quantity">−</button>
          <span>${quantity}</span>
          <button type="button" data-qty-product="${product.id}" data-qty-delta="1" aria-label="Increase ${product.name} quantity">+</button>
        </div>
      </div>
      <button class="remove-button" type="button" data-remove-product="${product.id}">Remove</button>
    </article>
  `).join("");
}

function addToCart(productId, quantity = 1) {
  if (!getProduct(productId)) return;
  const safeQuantity = Math.max(1, Number(quantity) || 1);
  cart[productId] = (cart[productId] || 0) + safeQuantity;
  saveCart();
  renderCart();
  showToast(`${getProduct(productId).name} added to cart`);
}

function updateQuantity(productId, delta) {
  if (!cart[productId]) return;
  const nextQuantity = cart[productId] + Number(delta);

  if (nextQuantity <= 0) {
    delete cart[productId];
  } else {
    cart[productId] = Math.min(nextQuantity, 99);
  }

  saveCart();
  renderCart();
}

function removeFromCart(productId) {
  if (!cart[productId]) return;
  delete cart[productId];
  saveCart();
  renderCart();
  showToast("Item removed");
}

function clearCart() {
  cart = {};
  saveCart();
  renderCart();
  showToast("Cart cleared");
}

function addBundle(bundleName) {
  const bundleIds = bundleName === "all-four"
    ? ["1-key", "2-key", "3-key", "4-key"]
    : ["1-key", "2-key"];

  bundleIds.forEach((id) => {
    cart[id] = (cart[id] || 0) + 1;
  });

  saveCart();
  renderCart();
  openCart();
  showToast(bundleName === "all-four" ? "Click Crew added" : "Mini Mix added");
}

function openCart() {
  cartDrawer.classList.add("open");
  cartOverlay.classList.add("open");
  cartDrawer.setAttribute("aria-hidden", "false");
  cartOverlay.setAttribute("aria-hidden", "false");
  openCartButton.setAttribute("aria-expanded", "true");
  document.body.style.overflow = "hidden";
  closeCartButton.focus();
}

function closeCart() {
  cartDrawer.classList.remove("open");
  cartOverlay.classList.remove("open");
  cartDrawer.setAttribute("aria-hidden", "true");
  cartOverlay.setAttribute("aria-hidden", "true");
  openCartButton.setAttribute("aria-expanded", "false");
  document.body.style.overflow = "";
}

function buildOrderSummary() {
  const lines = [];

  cartEntries().forEach(({ product, quantity }) => {
    lines.push(`${quantity} × ${product.name} — ${formatMoney(product.price * quantity)}`);
    if (product.configurationText) lines.push(`   ${product.configurationText}`);
  });

  lines.push(``, `Subtotal: ${formatMoney(cartTotal())}`);
  return lines.join("\n");
}

function beginCheckout() {
  if (cartItemCount() === 0) return;

  if (CHECKOUT_URL.trim()) {
    window.location.href = CHECKOUT_URL;
    return;
  }

  checkoutSummary.textContent = buildOrderSummary();
  checkoutMessage.innerHTML = "Your cart is ready. Add a hosted payment link to <code>CHECKOUT_URL</code> in <code>app.js</code> to send customers to a real payment page.";
  checkoutModal.classList.add("open");
  closeCart();
  closeCheckoutButton.focus();
}

async function copyOrderSummary() {
  const summary = buildOrderSummary();
  try {
    await navigator.clipboard.writeText(summary);
    showToast("Order summary copied");
  } catch {
    const textarea = document.createElement("textarea");
    textarea.value = summary;
    document.body.appendChild(textarea);
    textarea.select();
    document.execCommand("copy");
    textarea.remove();
    showToast("Order summary copied");
  }
}

function closeCheckout() {
  checkoutModal.classList.remove("open");
}

function showToast(message) {
  clearTimeout(toastTimer);
  toast.textContent = message;
  toast.classList.add("show");
  toastTimer = setTimeout(() => toast.classList.remove("show"), 1800);
}


function builderBaseProduct() {
  return PRODUCTS.find((product) => product.id === `${builderState.keyCount}-key`);
}

function renderBuilder() {
  if (!builderKeyCountOptions) return;

  builderKeyCountOptions.querySelectorAll("[data-builder-key-count]").forEach((button) => {
    button.classList.toggle("selected", Number(button.dataset.builderKeyCount) === builderState.keyCount);
  });

  builderSwitchOptions.querySelectorAll("[data-builder-switch]").forEach((button) => {
    button.classList.toggle("selected", button.dataset.builderSwitch === builderState.switchType);
  });

  builderPositions.innerHTML = builderState.keycaps.map((keycapId, index) => {
    const keycap = KEYCAPS.find((item) => item.id === keycapId);
    const preview = keycap
      ? `<img class="key-position-thumb" src="${keycap.image}" alt="">`
      : `<span class="key-position-placeholder" aria-hidden="true">+</span>`;

    return `
      <button class="key-position-button ${index === builderState.activePosition ? "active" : ""}" type="button" data-builder-position="${index}">
        ${preview}
        <span>Key ${index + 1}</span>
      </button>
    `;
  }).join("");

  const activeKeycapId = builderState.keycaps[builderState.activePosition];
  builderKeycapGrid.innerHTML = KEYCAPS.map((keycap) => `
    <button class="keycap-option ${activeKeycapId === keycap.id ? "selected" : ""}" type="button" data-builder-keycap="${keycap.id}" aria-label="Choose Keycap ${keycap.id} for key ${builderState.activePosition + 1}">
      <img src="${keycap.image}" alt="Keycap ${keycap.id}">
      <span>#${keycap.id}</span>
    </button>
  `).join("");

  const baseProduct = builderBaseProduct();
  const complete = builderState.keycaps.every(Boolean);
  const keycapSummary = builderState.keycaps
    .map((id, index) => `Key ${index + 1}: ${id ? `#${id}` : "not selected"}`)
    .join(" • ");

  builderPrice.textContent = formatMoney(baseProduct.price);
  builderSummary.innerHTML = `
    <strong>${builderState.keyCount}-Key • ${capitalize(builderState.switchType)}</strong><br>
    ${keycapSummary}
  `;

  builderAddButton.disabled = !complete;
  builderAddButton.style.opacity = complete ? "1" : ".55";
  builderAddButton.style.cursor = complete ? "pointer" : "not-allowed";
  builderAddButton.textContent = complete
    ? `Add custom clicker — ${formatMoney(baseProduct.price)}`
    : "Choose every keycap to add";
}

function setBuilderKeyCount(keyCount) {
  const nextCount = Math.max(1, Math.min(4, Number(keyCount) || 1));
  const existing = builderState.keycaps.slice(0, nextCount);

  while (existing.length < nextCount) existing.push(null);

  builderState.keyCount = nextCount;
  builderState.keycaps = existing;
  builderState.activePosition = Math.min(builderState.activePosition, nextCount - 1);
  renderBuilder();
}

function chooseBuilderKeycap(keycapId) {
  const id = Number(keycapId);
  if (!KEYCAPS.some((keycap) => keycap.id === id)) return;

  builderState.keycaps[builderState.activePosition] = id;

  const nextEmpty = builderState.keycaps.findIndex((value, index) => !value && index > builderState.activePosition);
  if (nextEmpty !== -1) {
    builderState.activePosition = nextEmpty;
  } else {
    const anyEmpty = builderState.keycaps.findIndex((value) => !value);
    if (anyEmpty !== -1) builderState.activePosition = anyEmpty;
  }

  renderBuilder();
}

function builderProductId() {
  if (!builderState.keycaps.every(Boolean)) return null;
  return `custom-${builderState.keyCount}-${builderState.switchType}-${builderState.keycaps.join(".")}`;
}

builderKeyCountOptions?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-builder-key-count]");
  if (button) setBuilderKeyCount(button.dataset.builderKeyCount);
});

builderSwitchOptions?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-builder-switch]");
  if (!button) return;
  builderState.switchType = button.dataset.builderSwitch;
  renderBuilder();
});

builderPositions?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-builder-position]");
  if (!button) return;
  builderState.activePosition = Number(button.dataset.builderPosition);
  renderBuilder();
});

builderKeycapGrid?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-builder-keycap]");
  if (button) chooseBuilderKeycap(button.dataset.builderKeycap);
});

builderAddButton?.addEventListener("click", () => {
  const productId = builderProductId();
  if (!productId) {
    showToast("Choose a keycap for every key");
    return;
  }

  addToCart(productId);
  openCart();
});

productGrid.addEventListener("click", (event) => {
  const button = event.target.closest("[data-add-product]");
  if (!button) return;
  addToCart(button.dataset.addProduct);
});

cartItems.addEventListener("click", (event) => {
  const quantityButton = event.target.closest("[data-qty-product]");
  if (quantityButton) {
    updateQuantity(quantityButton.dataset.qtyProduct, Number(quantityButton.dataset.qtyDelta));
    return;
  }

  const removeButton = event.target.closest("[data-remove-product]");
  if (removeButton) removeFromCart(removeButton.dataset.removeProduct);
});

document.querySelectorAll(".bundle-add").forEach((button) => {
  button.addEventListener("click", () => addBundle(button.dataset.bundle));
});

openCartButton.addEventListener("click", openCart);
shopCartButton.addEventListener("click", openCart);
closeCartButton.addEventListener("click", closeCart);
cartOverlay.addEventListener("click", closeCart);
clearCartButton.addEventListener("click", clearCart);
checkoutButton.addEventListener("click", beginCheckout);
copyOrderButton.addEventListener("click", copyOrderSummary);
closeCheckoutButton.addEventListener("click", closeCheckout);
checkoutModal.addEventListener("click", (event) => {
  if (event.target === checkoutModal) closeCheckout();
});

document.addEventListener("keydown", (event) => {
  if (event.key !== "Escape") return;
  if (checkoutModal.classList.contains("open")) closeCheckout();
  else if (cartDrawer.classList.contains("open")) closeCart();
});

renderProducts();
renderCart();
renderBuilder();


const heroProductImage = document.getElementById("heroProductImage");
if (heroProductImage) heroProductImage.src = PRODUCTS[3].image;
